package ma.projet.beans;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Inheritance(strategy=InheritanceType.JOINED) @Table(name="personne") public abstract class Personne { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String nom,prenom; private String telephone,adresse; private LocalDate dateNaissance; protected Personne(){} protected Personne(String n,String p,String t,String a,LocalDate d){nom=n;prenom=p;telephone=t;adresse=a;dateNaissance=d;} public Long getId(){return id;} public String getNom(){return nom;} public String getPrenom(){return prenom;} public String getTelephone(){return telephone;} public String getAdresse(){return adresse;} public LocalDate getDateNaissance(){return dateNaissance;} public String toString(){return prenom+" "+nom;} }
